		db.Node("said");
		db.Jump("caught", "wrong");
		db.Say("", "Notebook {cover:notebook}. Yes, that number is one of ours, night shift. Carry on, then, quietly. The incubators don't like noise.");
		db.Choice("back1", "Thank you.", "hub", "", "", "", "", "", "", "", "");
		db.Node("wrong");
		db.Say("", "There is no notebook with that number. There never was. I'm calling the guard, and I'm writing down that you tried.");
		db.Choice("back2", "Understood.", "hub", "", "", "", "", "", "", "", "");
		db.Conv("named.halcyon.kit_issued", "named:halcyon", "kit:issued & !tier:halcyon>=known", "", 4, 6, "halcyon");
		db.Node("start");
		db.Say("kit:issued", "That coat is on our stores register, issued against your name when the lab still trusted you. Your name is on a different list now. Please return the coat to the quartermaster.");
		db.Conv("named.redhand.kit_issued", "named:redhand", "kit:issued & !tier:redhand>=known", "", 4, 6, "redhand");
		db.Node("start");
