		db.Choice("claim", "One of yours. Let me through.", "passed", "caught", "", "look bastion 2", "", "", "", "", "");
		db.Choice("truth", "Took it off a dead man. I'm not yours.", "honest", "", "", "", "", "", "", "", "");
		db.Choice("leave", "Forget it. I'll go back the way I came.", "hub", "", "", "", "", "", "", "", "");
		db.Node("passed");
		db.Say("", "Fine. Must be the new draft down from the hills. Go on, and keep your head down past the sandbags. We're short of heads as it is.");
