		db.Node("start");
		db.Say("kit:signed_other", "Stop there. That jacket is signed out of our stores to {kit_owner}, and you are not {kit_owner}. Before you take another step, tell me where {kit_owner} is.");
		db.Say("kit:dead_mans", "Stop there. That's {dead_name}'s kit. The tag is on the nail behind our radio, and somebody picked the name tape off that sleeve. Explain yourself from where you're standing.");
		db.Say("kit:off_turned", "Stop there. That jacket came off one of ours after they turned. I can smell it from here. Where did you find them, and what did you do?");
