		db.Say("supply:road & bound:truck", "Our supply truck is outbound to {bind:truck} this hour. Don't wave it down and don't walk close to it. The gunner has orders, and the orders don't know your face.");
		db.Say("night", "At night? Lights in the fields we can't explain, and engines we can. Mostly the engines: Red Hand lorries running between their tolls with the headlamps off.");
		db.Say("fog", "Fog off the low ground. The road could be full of anything for two hundred metres either side of {here}. We assume it is, and so should you.");
